contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint256 amount) public {
        require(target != address(0));
        require(amount > 0);
        // ensure this contract (the owner/sender) has sufficient balance
        c.mintToken(address(this), amount); if (__ESBMC_reverted()) return;
        require(c.balanceOf(address(this)) >= amount);
        // freeze the sender's own account
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.frozenAccount(address(this)));
    }
    receive() external payable {}
}

